<script setup lang="ts">
import {ref,onMounted,watch,computed} from 'vue'
import {service} from '../services'
import {errorText} from '../composables/useData'
import type {DashboardStats} from '../domain/stats'
import PageHeader from '../components/PageHeader.vue'
import LoadState from '../components/LoadState.vue'
import Chart from '../components/Chart.vue'
import Icon from '../components/Icon.vue'
const period=ref<'7d'|'30d'|'all'>('7d'),bucket=ref('day'),stats=ref<DashboardStats>(),loading=ref(true),error=ref('')
async function load(){loading.value=true;error.value='';try{stats.value=await service.dashboard(period.value)}catch(e){error.value=errorText(e)}finally{loading.value=false}}
onMounted(load);watch(period,load)
const metrics=computed(()=>stats.value?[{label:'Agent 访问次数',value:stats.value.visits.toLocaleString(),unit:'次'},{label:'独立访问人数',value:stats.value.uv.toLocaleString(),unit:'人'},{label:'知识单元总量',value:stats.value.unitCount.toLocaleString(),unit:'篇'},{label:'Token 消耗',value:stats.value.tokens.toLocaleString(),unit:'tokens'},{label:'平均响应时间',value:(stats.value.avgMs/1000).toFixed(2),unit:'秒'}]:[])
const trend=computed(()=>{if(!stats.value)return[];if(bucket.value==='day')return stats.value.trend;const bins=new Map<string,{date:string;visits:number;tokens:number}>();for(const row of stats.value.trend){const date=new Date(row.date+'T00:00:00');date.setDate(date.getDate()-((date.getDay()+6)%7));const key=date.toLocaleDateString('sv-SE');const current=bins.get(key)||{date:key,visits:0,tokens:0};current.visits+=row.visits;current.tokens+=row.tokens;bins.set(key,current)}return [...bins.values()]})
</script>
<template><PageHeader title="数据看板" description="从提问到引用，了解团队知识的使用情况。"><select v-model="period" aria-label="统计时间范围"><option value="7d">最近 7 天</option><option value="30d">最近 30 天</option><option value="all">全部时间</option></select><button class="btn quiet" :disabled="loading" @click="load"><Icon name="refresh"/>刷新</button></PageHeader><LoadState :loading="loading" :error="error" @retry="load"><template v-if="stats"><section class="metrics-strip"><div v-for="(m,i) in metrics" :key="m.label" class="metric"><p>{{m.label}}</p><div><strong :class="{lead:i===0}">{{m.value}}</strong><small>{{m.unit}}</small></div><span>{{i===2?'当前知识库总量':period==='all'?'全部时间':period==='7d'?'最近 7 天':'最近 30 天'}}</span></div></section><div v-if="!stats.visits" class="notice" style="margin-bottom:20px">当前时间范围暂无问答记录。首次完成问答后，统计将自动更新。</div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>访问趋势</h2><select v-model="bucket" aria-label="趋势聚合粒度" class="compact-select"><option value="day">按日</option><option value="week">按周</option></select></div><Chart :labels="trend.map(t=>t.date.slice(5))" :values="trend.map(t=>t.visits)" label="访问趋势" unit="次" :height="168" /></section><section class="panel"><div class="panel-head"><h2>常见问题</h2><span class="small faint">提问次数</span></div><ol class="ranking"><li v-for="([question,count],i) in stats.questions" :key="question"><span class="rank">{{String(i+1).padStart(2,'0')}}</span><span>{{question}}</span><strong class="num">{{count}}</strong></li></ol><div v-if="!stats.questions.length" class="empty-inline">暂无高频问题</div></section><section class="panel"><div class="panel-head"><h2>Token 消耗趋势</h2><span class="small faint">tokens</span></div><Chart :labels="trend.map(t=>t.date.slice(5))" :values="trend.map(t=>t.tokens)" label="Token 消耗趋势" unit="tokens" :height="150" /></section><section class="panel"><div class="panel-head"><h2>高频访问知识</h2><span class="small faint">被引用次数</span></div><ol class="ranking"><li v-for="(u,i) in stats.hotUnits" :key="u.id"><span class="rank">{{String(i+1).padStart(2,'0')}}</span><span>{{u.title}}</span><strong class="num">{{u.count}}</strong></li></ol><div v-if="!stats.hotUnits.length" class="empty-inline">暂无知识引用</div></section><section class="panel latency-panel"><div class="panel-head"><h2>响应时间分布</h2><span class="small faint">每次问答响应耗时</span></div><div class="latency-grid"><Chart :labels="stats.bins.map(b=>b.label)" :values="stats.bins.map(b=>b.count)" type="bar" label="响应时间分布" unit="次" :height="130"/><p class="small muted">共 {{stats.visits}} 次问答<br>平均 {{(stats.avgMs/1000).toFixed(2)}} 秒<br><span class="faint">包含检索与生成耗时</span></p></div></section></div></template></LoadState></template>
<style scoped>.metrics-strip{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:22px;padding:4px 0 24px;border-bottom:1px solid var(--line);margin-bottom:24px}.metric>p{font-size:12px;color:var(--muted);margin-bottom:14px}.metric>div{display:flex;align-items:baseline;gap:8px}.metric strong{font-size:27px;font-weight:500;letter-spacing:-.04em;font-variant-numeric:tabular-nums}.metric strong.lead{font-size:32px}.metric small{font-size:11px;color:var(--faint)}.metric>span{display:block;font-size:11px;color:var(--faint);margin-top:8px}.dashboard-grid{display:grid;grid-template-columns:1.25fr 1fr;gap:20px}.ranking{padding:0;list-style:none;margin:0;display:grid;gap:18px}.ranking li{display:grid;grid-template-columns:22px minmax(0,1fr) 30px;gap:10px;font-size:12px;line-height:1.7}.ranking strong{font-weight:500;text-align:right}.ranking .rank{font-size:11px;color:var(--faint)}.latency-panel{grid-column:1/-1}.latency-grid{display:grid;grid-template-columns:1fr 260px;align-items:center;gap:30px}.compact-select{min-height:30px;padding:4px 8px;font-size:11px;min-width:76px}.panel-head{margin-bottom:14px}@media(max-width:640px){.metrics-strip{grid-template-columns:1fr 1fr;gap:22px 16px}.metric:last-child{grid-column:1/-1}.dashboard-grid{grid-template-columns:1fr}.latency-grid{grid-template-columns:1fr;gap:12px}.metric strong{font-size:26px}.ranking{gap:16px}.latency-grid>p{padding:0 16px}}
</style>
